        const movingColorsB = [ settings.color2, settings.color3, settings.color1 ];
        const movingColorsC = [ settings.color3, settings.color1, settings.color2 ];
        const movingShadowA = currentGlowStyle === STYLE_INNER_AURA
                ? shadowBuilder(1)
                : shadowBuilder(1, movingColorsA);
        const movingShadowB = currentGlowStyle === STYLE_INNER_AURA
                ? shadowBuilder(1)
                : shadowBuilder(1, movingColorsB);
        const movingShadowC = currentGlowStyle === STYLE_INNER_AURA
                ? shadowBuilder(1)
                : shadowBuilder(1, movingColorsC);
        const mainColor = getMainNeonColor();
        if (currentGlowStyle === STYLE_NEON_80S) {
            overlay.style.background = 'transparent';
            overlay.style.borderImageSource = 'none';
            overlay.style.borderImageSlice = '';
            overlay.style.borderImageWidth = '';
            overlay.style.borderImageOutset = '';
            overlay.style.border =
                `2px solid rgba(255,255,255,0.98)`;
        } else if ( currentGlowStyle === STYLE_INNER_AURA ) {
            overlay.style.background = 'transparent';
            overlay.style.borderImageSource = 'none';
            overlay.style.borderImageSlice = '';
            overlay.style.borderImageWidth = '';
            overlay.style.borderImageOutset = '';
            overlay.style.border = '0 solid transparent';
        } else {
            overlay.style.background = 'transparent';
            overlay.style.borderImageSource = 'none';
            overlay.style.borderImageSlice = '';
            overlay.style.borderImageWidth = '';
            overlay.style.borderImageOutset = '';
            overlay.style.border = mainColor === 'transparent'
                    ? '0 solid transparent'
                    : `2px solid ${hexToRgba(mainColor, 0.98)}`;
        }
        const animationSignature = JSON.stringify({
            glowStyle: Number(settings.glowStyle) || 1, neonColors: [ settings.color1, settings.color2, settings.color3 ], effect, enabled: pulse.enabled, duration: pulse.duration,
            baseShadow, peakShadow, softShadow, movingShadowA, movingShadowB, movingShadowC
        });
