                const centerY = Number(badge.dataset.sgCenterY);
                if ( !Number.isFinite(centerX) || !Number.isFinite(centerY) ) {
                    continue;
                }
                const covered = tooltips.some(({ rect: tip }) => centerX >= tip.left && centerX <= tip.right && centerY >= tip.top && centerY <= tip.bottom );
                const nextOpacity = covered
